import React from "react";

export default function About() {
  return (
    <div className="about-page">

      {/* HERO */}
      <div className="hero">
        <h1>
          I’m a developer who turns <span>ideas into systems</span>.
        </h1>

        <p>
          Information Technology student • Builder • Problem solver
        </p>
      </div>

      {/* STORY FLOW */}
      <div className="story">

        <div className="line-block">
          <div className="dot"></div>
          <div className="text">
            <h2>Thinking Style</h2>
            <p>
              I approach problems by simplifying them into structured components.
              Instead of jumping into code, I focus on understanding how each part
              of a system interacts before building.
            </p>
          </div>
        </div>

        <div className="line-block">
          <div className="dot"></div>
          <div className="text highlight">
            <h2>How I Work</h2>
            <p>
              Build → Test → Improve → Repeat. Every project is an iterative process
              where I refine logic, improve structure, and optimize clarity in code.
            </p>
          </div>
        </div>

        <div className="line-block">
          <div className="dot"></div>
          <div className="text">
            <h2>What I Focus On</h2>
            <p>
              Full-stack development, UI clarity, backend logic, and building
              real-world applications that solve practical problems.
            </p>
          </div>
        </div>

      </div>

      {/* INFO STRIP */}
      <div className="info-strip">

        <div className="box">
          <h3>🎓 Education</h3>
          <p>B.Tech – IT</p>
          <p className="muted">Panimalar Engineering College</p>
          <div className="row">
            <span>2023–2027</span>
            <span className="cgpa">CGPA: 8.81</span>
          </div>
        </div>

        <div className="box">
          <h3>📌 Interests</h3>
          <p>Java • Full Stack • UI Design • AI Basics • DBMS</p>
        </div>

      </div>

      <style>{`

        .about-page {
          min-height: 100vh;
          padding: 60px 10%;
          font-family: "Poppins", sans-serif;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
        }

        /* HERO */
        .hero h1 {
          font-size: 44px;
          line-height: 1.3;
        }

        .hero span {
          color: #38BDF8;
        }

        .hero p {
          color: #94a3b8;
          margin-top: 10px;
        }

        /* STORY FLOW */
        .story {
          margin-top: 50px;
          position: relative;
        }

        .line-block {
          display: flex;
          gap: 15px;
          margin-bottom: 35px;
          position: relative;
        }

        .dot {
          width: 10px;
          height: 10px;
          margin-top: 10px;
          border-radius: 50%;
          background: #38BDF8;
          box-shadow: 0 0 10px #38BDF8;
        }

        .text {
          padding-left: 10px;
        }

        .text h2 {
          color: #38BDF8;
          margin-bottom: 6px;
        }

        .text p {
          color: #cbd5e1;
          line-height: 1.7;
        }

        .highlight {
          border-left: 2px solid rgba(56,189,248,0.4);
          padding-left: 14px;
        }

        /* INFO STRIP */
        .info-strip {
          margin-top: 60px;
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 20px;
        }

        .box {
          padding: 18px;
          border-radius: 14px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.15);
        }

        .box h3 {
          color: #38BDF8;
          margin-bottom: 8px;
        }

        .box p {
          color: #cbd5e1;
        }

        .muted {
          color: #94a3b8;
        }

        .row {
          display: flex;
          justify-content: space-between;
          margin-top: 10px;
        }

        .cgpa {
          color: #38BDF8;
          font-weight: 600;
        }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .hero h1 {
            font-size: 32px;
          }

          .info-strip {
            grid-template-columns: 1fr;
          }
        }

      `}</style>

    </div>
  );
}
